mapper.sql:
SELECT DISTINCT cf.resource_id
FROM customer_field cf
JOIN sys_module_field f ON f.id = cf.field_id AND f.internal_key = 'customerArea'
JOIN sys_module_form m ON m.id = f.form_id AND m.form_key = 'customer' AND m.organization_id = #{orgId}
WHERE cf.field_value IS NOT NULL AND cf.field_value != ''
  AND CONCAT(LEFT(cf.field_value, 2), '0000') = #{adcode}

mapper.select:
SELECT
    (SELECT COALESCE(SUM(amount), 0) FROM contract WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND (void_reason IS NULL OR void_reason = '')) AS contractAmount,
    (SELECT COUNT(*) FROM contract WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND (void_reason IS NULL OR void_reason = '')) AS contractCount,
    (SELECT COALESCE(SUM(record_amount), 0) FROM contract_payment_record WHERE organization_id = #{orgId}
     AND owner = #{ownerId} AND verification_status = 'DONE') AS verifiedAmount,
    (SELECT COUNT(*) FROM customer WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND in_shared_pool = 0) AS customerCount,
    (SELECT COUNT(*) FROM clue WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND in_shared_pool = 0 AND (transition_type IS NULL OR transition_type != 'CUSTOMER')) AS clueCount,
    (SELECT COUNT(*) FROM opportunity WHERE organization_id = #{orgId} AND owner = #{ownerId}) AS opportunityCount,
    (SELECT COUNT(*) FROM customer WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND in_shared_pool = 0 AND create_time >= #{monthStart}) AS monthNewCustomer,
    (SELECT COUNT(*) FROM contract WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND (void_reason IS NULL OR void_reason = '') AND start_time >= #{monthStart}) AS monthNewContract,
    (SELECT COALESCE(SUM(amount), 0) FROM contract WHERE organization_id = #{orgId} AND owner = #{ownerId}
     AND (void_reason IS NULL OR void_reason = '') AND start_time >= #{monthStart}) AS monthNewContractAmount
